INSERT INTO public.exam_questions (id, subject_name, subject_slug, topic, text, answer, kind, type, for_exam, for_ticket, source, is_published)
VALUES ('835b5187-d842-5632-aae9-d7f498881f22'::uuid, 'Гистология, цитология', 'histology', 'Эмбриогенез', 'При развитии эмбриона человека образуется желточный мешок, который не содержит желтка. Какими листками он образован? Какие функции выполняет этот орган?', '1) альвеолярные макрофаги, 2) из моноцитов крови, 3) фагоцитоз', 'ticket', 'case', true, true, 'features/exam-questions', true)
ON CONFLICT (id) DO UPDATE SET text = EXCLUDED.text, answer = EXCLUDED.answer, topic = EXCLUDED.topic, is_published = true;
INSERT INTO public.exam_questions (id, subject_name, subject_slug, topic, text, answer, kind, type, for_exam, for_ticket, source, is_published)
VALUES ('3d51bb74-ae8d-5cc9-a1c1-5da7c10c308f'::uuid, 'Гистология, цитология', 'histology', 'Эмбриогенез', 'Какие органеллы придают цитоплазме базофильные свойства и какую функцию они выполняют? Приведите примеры клеток с базофильной цитоплазмой. Объясните, какая органелла устанавливает хромосомы в метафазе и какие процессы в делении происходят в дальнейшем при ее участии. Объясните, за счет каких клеток происходит регенерация поперечнополосатых мышечных волокон. Какой процесс в ходе регенерации сменит период размножения клеток?', 'Наличие выраженного мышечного слоя, отсутствие хрящевого каркаса.', 'ticket', 'case', true, true, 'features/exam-questions', true)
ON CONFLICT (id) DO UPDATE SET text = EXCLUDED.text, answer = EXCLUDED.answer, topic = EXCLUDED.topic, is_published = true;
INSERT INTO public.exam_questions (id, subject_name, subject_slug, topic, text, answer, kind, type, for_exam, for_ticket, source, is_published)
VALUES ('e637bfeb-9112-5259-aff0-2448e1bf7084'::uuid, 'Гистология, цитология', 'histology', 'Эмбриогенез', 'Наблюдаема в условиях высокогорья одышка со временем уменьшается. объясните возможный механизм данной адаптации. Какое количество эритроцитов в 1 л в норме у мужчин и женщин?', 'Смерть ребенка наступила до 1-го вдоха.', 'ticket', 'case', true, true, 'features/exam-questions', true)
ON CONFLICT (id) DO UPDATE SET text = EXCLUDED.text, answer = EXCLUDED.answer, topic = EXCLUDED.topic, is_published = true;
INSERT INTO public.exam_questions (id, subject_name, subject_slug, topic, text, answer, kind, type, for_exam, for_ticket, source, is_published)
VALUES ('61ea7c24-c82f-53cb-9eb5-abaa9c7e5c83'::uuid, 'Гистология, цитология', 'histology', 'Эмбриогенез', 'При анализе желудочного сока у больного выявлены низкие показатели кислотности. С гиперфункцией каких клеток желез желудка можно связать этот факт? Какое положение в железе они занимают?', 'С меньшей длиной нефрона.', 'ticket', 'case', true, true, 'features/exam-questions', true)
ON CONFLICT (id) DO UPDATE SET text = EXCLUDED.text, answer = EXCLUDED.answer, topic = EXCLUDED.topic, is_published = true;
INSERT INTO public.exam_questions (id, subject_name, subject_slug, topic, text, answer, kind, type, for_exam, for_ticket, source, is_published)
VALUES ('2f84ca73-9d14-5302-a0d0-08749e01e2e4'::uuid, 'Гистология, цитология', 'histology', 'Эмбриогенез', 'Внутренняя поверхность альвеол выстлана особым слоем, снижающим ее адгезивные свойства. Назовите этот слой. Какие клетки его секретируют и какие клетки его разрушают?', '1) в наружной зоне коркового вещества. 2) юкстамедулярная.', 'ticket', 'case', true, true, 'features/exam-questions', true)
ON CONFLICT (id) DO UPDATE SET text = EXCLUDED.text, answer = EXCLUDED.answer, topic = EXCLUDED.topic, is_published = true;
INSERT INTO public.exam_questions (id, subject_name, subject_slug, topic, text, answer, kind, type, for_exam, for_ticket, source, is_published)
VALUES ('398707e5-f9a2-5023-bc8a-8b4a70d0a02e'::uuid, 'Гистология, цитология', 'histology', 'Эмбриогенез', 'В препарате легкого мертворожденного наблюдается сплошь не расправленные альвеолы, заполненные жидкостью. Какое объяснение имеет этот факт?', '1) 12-14-й день цикла. 2) эстрогены.', 'ticket', 'case', true, true, 'features/exam-questions', true)
