VALUES ('d1839f69-78c8-58dd-ab81-4eb16255cd1b'::uuid, 'Гистология, цитология', 'histology', 'Эмбриогенез', 'С какой органеллой взаимодейст-вует фагоцитарная частица?', '1) 14-15-й дни. 2) 1-2 суток.', 'ticket', 'case', true, true, 'features/exam-questions', true)
