VALUES ('f6133000-1ba7-59cd-a55c-e8bfa773dd23'::uuid, 'Гистология, цитология', 'histology', 'В чем заключается различие их', 'строения?', 'В момент имплантации у зародыша человека имеются: трофобласт с полостью, эпибласт с полостью, гипобласт и внезародышевая мезодерма (мезенхима). Имплантация происходит на 7 сутки после оплодотворения.', 'ticket', 'case', true, true, 'features/exam-questions', true)
ON CONFLICT (id) DO UPDATE SET text = EXCLUDED.text, answer = EXCLUDED.answer, topic = EXCLUDED.topic, is_published = true;
