VALUES ('9f54bb99-ddda-5e41-9b24-2d01756e313d'::uuid, 'Гистология, цитология', 'histology', 'В чем заключается различие их', 'Какова плоидность ДНК в клеточном ядре перед митозом и сразу после его завершения?', 'Кроме сперматозоидов гаплоидные ядра имеют сперматиды. Оплодотворить яйцеклетку они не могут.', 'ticket', 'case', true, true, 'features/exam-questions', true)
